{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "WAY-100635, the closest analogue with a cyclohexanecarbonyl group instead of the norbornanecarbonyl group, showed good maximal brain uptake of 5.0% ID in cynomolgus monkeys by PET, demonstrating meaningful CNS access despite any efflux liability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Tritiated WAY-100635 injected i.v. in mice distributed in the brain in a receptor-specific manner, directly confirming that this scaffold penetrates the blood-brain barrier.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "The close 4-fluorocyclohexane analogue FCWAY is BBB-permeable and has been used as a 5-HT1A PET tracer in rodents and humans, supporting CNS access for the broader WAY-100635 scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "The 4-fluoromethylcyclohexane analogue 18F-mefway showed rapid human brain uptake with a peak SUV of 1.7, providing direct human evidence for meaningful CNS penetration in this chemical series.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "The 6-fluoropyridyl analogue 6FPWAY showed rapid monkey brain uptake of 4.33% of the injected dose, further supporting robust brain penetration for close analogues of the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "The less similar benzoyl analogue MPPF is a P-gp substrate with relatively low rat brain uptake, indicating that efflux can reduce exposure in this scaffold class, but this is outweighed by direct brain-penetration data for the more structurally similar cyclohexane/norbornane analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a norbornanecarbonyl analogue of WAY-100635. Direct PET and biodistribution evidence in monkeys, mice, and humans for WAY-100635 and its close cyclohexane/fluorocyclohexane analogues demonstrates robust brain penetration. P-gp efflux is present in this series but does not prevent meaningful CNS access, and the iodinated high-logD analogues with poor uptake are structurally less relevant.",
  "evidence_gaps": [
    "No direct experimental measurement exists for the exact norbornanecarbonyl query analogue.",
    "Quantitative brain-to-plasma or unbound brain concentration data are not provided for the closest analogues.",
    "The impact of the norbornane group on P-gp recognition relative to cyclohexane is not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

